    // 1. Input Validation & Fault Handling
    if ((wp_input.wheels == NULL) || (wp_input.torque_nm == NULL) ||
        (wp_input.wheel_count != 4U)) {
        wp_state.mode = WP_FAULT;
        wp_output.mode = WP_FAULT;
        wp_output.clean = 0;
        wp_output.power_limited_mask = 0;
        wp_output.slew_limited_mask = 0;
        wp_output.requested_net_power_w = 0.0;
        wp_output.delivered_net_power_w = 0.0;
        wp_output.requested_motoring_power_w = 0.0;
        wp_output.requested_regenerative_power_w = 0.0;
        wp_output.delivered_motoring_power_w = 0.0;
        wp_output.delivered_regenerative_power_w = 0.0;
        wp_output.filtered_abs_power_w = 0.0;
        for (int i = 0; i < 4; i++) {
            wp_output.limited_torque_nm[i] = 0.0;
            wp_state.previous_torque_nm[i] = 0.0;
        }
        wp_output.momentum_norm_nms = 0.0;
        wp_output.momentum_nms.x = 0.0; wp_output.momentum_nms.y = 0.0; wp_output.momentum_nms.z = 0.0;
        wp_output.requested_body_torque_nm.x = 0.0; wp_output.requested_body_torque_nm.y = 0.0; wp_output.requested_body_torque_nm.z = 0.0;
        wp_output.delivered_body_torque_nm.x = 0.0; wp_output.delivered_body_torque_nm.y = 0.0; wp_output.delivered_body_torque_nm.z = 0.0;
        return;
    }

    // Config validation (implicit requirement)
    if (wp_config.release_filtered_w >= wp_config.trip_filtered_w ||
        wp_config.filter_alpha < 0.0 || wp_config.filter_alpha > 1.0 ||
        wp_config.motoring_limit_w <= 0.0 || wp_config.regenerative_limit_w <= 0.0 ||
        wp_config.max_torque_slew_nm_per_cycle <= 0.0 ||
        wp_config.release_cycles < 1 || wp_config.release_cycles > 20) {
        goto fault_handle;
    }

    // 2. Momentum Calculation
    adcs_vec3_t momentum_nms;
    adcs_status_t stat = adcs_wheel_momentum(wp_input.wheels, 4, &momentum_nms);
    if (stat != ADCS_OK || !adcs_is_finite_vec3(&momentum_nms)) {
        goto fault_handle;
    }

    double momentum_norm = adcs_vec3_norm(&momentum_nms);
    wp_output.momentum_nms = momentum_nms;
    wp_output.momentum_norm_nms = momentum_norm;

    double requested_motoring = 0.0;
    double requested_regenerative = 0.0;
    double requested_net = 0.0;
    unint32 power_limited_mask = 0;
    double delivered_motoring = 0.0;
    double delivered_regenerative = 0.0;

    double requested_body_tx = 0.0;
    double requested_body_ty = 0.0;
    double requested_body_tz = 0.0;

    double requested_torques[4];
    double limited_torques[4];
    unint32 slew_limited_mask = 0;
    int any_power_limited = 0;
    int any_slew_limited = 0;

    // 3. Per-Wheel Power and Torque Processing
    for (int i = 0; i < 4; i++) {
        double tau = wp_input.torque_nm[i];
        double speed = wp_input.wheels[i].speed_rad_s;
        requested_torques[i] = tau;

        // Mechanical Power
        double p = tau * speed;

        if (p >= 0.0) {
            requested_motoring += p;
        } else {
            requested_regenerative += (-p);
        }
        requested_net += p;

        // Body Torque Contribution: -tau * axis
        adcs_vec3_t axis = wp_input.wheels[i].axis_body;
        double anorm = sqrt(axis.x*axis.x + axis.y*axis.y + axis.z*axis.z);
        if (anorm < 1e-12) anorm = 1.0;

        requested_body_tx -= tau * (axis.x / anorm);
        requested_body_ty -= tau * (axis.y / anorm);
        requested_body_tz -= tau * (axis.z / anorm);
    }

    wp_output.requested_net_power_w = requested_net;
    wp_output.requested_motoring_power_w = requested_motoring;
    wp_output.requested_regenerative_power_w = requested_regenerative;
    wp_output.requested_body_torque_nm.x = requested_body_tx;
    wp_output.requested_body_torque_nm.y = requested_body_ty;
    wp_output.requested_body_torque_nm.z = requested_body_tz;

    // 4. Directional Power Limiting
    if (requested_motoring > wp_config.motoring_limit_w) {
        delivered_motoring = wp_config.motoring_limit_w;
        any_power_limited = 1;
        for (int i = 0; i < 4; i++) {
             if (requested_torques[i] * wp_input.wheels[i].speed_rad_s >= 0.0) {
                 power_limited_mask |= (1U << i);
             }
        }
    } else {
        delivered_motoring = requested_motoring;
    }

    if (requested_regenerative > wp_config.regenerative_limit_w) {
        delivered_regenerative = wp_config.regenerative_limit_w;
        any_power_limited = 1;
        for (int i = 0; i < 4; i++) {
             if (requested_torques[i] * wp_input.wheels[i].speed_rad_s < 0.0) {
                 power_limited_mask |= (1U << i);
             }
        }
    } else {
        delivered_regenerative = requested_regenerative;
    }

    wp_output.delivered_motoring_power_w = delivered_motoring;
    wp_output.delivered_regenerative_power_w = delivered_regenerative;
    wp_output.power_limited_mask = power_limited_mask;

    // 5. Slew Limiting
    for (int i = 0; i < 4; i++) {
        double prev_tau = wp_state.previous_torque_nm[i];
        double diff = requested_torques[i] - prev_tau;

        double max_delta = wp_config.max_torque_slew_nm_per_cycle;
        if (diff > max_delta) {
            limited_torques[i] = prev_tau + max_delta;
            slew_limited_mask |= (1U << i);
            any_slew_limited = 1;
        } else if (diff < -max_delta) {
            limited_torques[i] = prev_tau - max_delta;
            slew_limited_mask |= (1U << i);
            any_slew_limited = 1;
        } else {
            limited_torques[i] = requested_torques[i];
        }
    }

    wp_output.slew_limited_mask = slew_limited_mask;

    // Recalculate Delivered Body Torque based on Slewed/Delivered Torques
    double delivered_body_tx = 0.0;
    double delivered_body_ty = 0.0;
    double delivered_body_tz = 0.0;

    for (int i = 0; i < 4; i++) {
        double tau = limited_torques[i];
        adcs_vec3_t axis = wp_input.wheels[i].axis_body;
        double anorm = sqrt(axis.x*axis.x + axis.y*axis.y + axis.z*axis.z);
        if (anorm < 1e-12) anorm = 1.0;

        delivered_body_tx -= tau * (axis.x / anorm);
        delivered_body_ty -= tau * (axis.y / anorm);
        delivered_body_tz -= tau * (axis.z / anorm);
    }

    wp_output.delivered_body_torque_nm.x = delivered_body_tx;
    wp_output.delivered_body_torque_nm.y = delivered_body_ty;
    wp_output.delivered_body_torque_nm.z = delivered_body_tz;

    for (int i = 0; i < 4; i++) {
        wp_output.limited_torque_nm[i] = limited_torques[i];
    }

    // 6. Filtered Power Calculation
    double abs_net = fabs(requested_net);
    double new_filtered = wp_config.filter_alpha * abs_net + (1.0 - wp_config.filter_alpha) * wp_state.filtered_abs_power_w;
    wp_state.filtered_abs_power_w = new_filtered;
    wp_output.filtered_abs_power_w = new_filtered;

    // 7. State Machine Transition
    wp_mode_t next_mode = wp_state.mode;
    unint32 next_clean = wp_state.clean;

    // Check conditions for LIMITED
    if (any_power_limited || any_slew_limited || (new_filtered >= wp_config.trip_filtered_w)) {
        next_mode = WP_LIMITED;
        next_clean = 0;
    } else {
        // No limits active
        if (new_filtered <= wp_config.release_filtered_w) {
            if (wp_state.mode != WP_RECOVERING) {
                next_mode = WP_RECOVERING;
                next_clean = 1;
            } else {
                next_clean = wp_state.clean + 1;
                if (next_clean >= wp_config.release_cycles) {
                    next_mode = WP_NORMAL;
                    next_clean = 0;
                }
            }
        } else {
            // High filtered power, no physical limits -> fallback to LIMITED if trying to recover
            if (wp_state.mode == WP_RECOVERING || wp_state.mode == WP_NORMAL) {
                 next_mode = WP_LIMITED;
                 next_clean = 0;
            }
        }
    }

    // Update State
    wp_state.mode = next_mode;
    wp_state.clean = next_clean;

    // Save previous torques for next cycle slew limiting
    for (int i = 0; i < 4; i++) {
        wp_state.previous_torque_nm[i] = limited_torques[i];
    }

    // Fill Output Mode
    wp_output.mode = next_mode;
    wp_output.clean = next_clean;

    return;

